const CAPTURE_SPEECH_REC = window.SpeechRecognition
    || window.webkitSpeechRecognition
    || null;
let _captureVoiceRec = null;
// Press-to-talk dictation into #qlInput. The transcript (interim + final) flows
// through the same quick-log routing as typed text. Degrades to text-only where
// speech is absent.
function setupCaptureVoice(deps) {
    const mic = deps.root.querySelector("#qlMic");
    const inp = deps.root.querySelector("#qlInput");
    if (!mic || !inp)
        return;
    if (!CAPTURE_SPEECH_REC) {
        mic.hidden = true;
        return;
    }
    mic.hidden = false;
    const stop = () => {
        if (_captureVoiceRec) {
            try {
                _captureVoiceRec.stop();
            }
            catch { }
            _captureVoiceRec = null;
        }
        mic.classList.remove("qlmic-live");
    };
    mic.addEventListener("click", () => {
        if (_captureVoiceRec) {
            stop();
            return;
        }
        let rec;
        try {
            rec = new CAPTURE_SPEECH_REC();
        }
        catch {
            mic.hidden = true;
            return;
        }
        rec.lang = navigator.language || "en-US";
        rec.interimResults = true;
        rec.continuous = false;
        rec.maxAlternatives = 1;
        const base = inp.value.trim();
        let finalText = "";
        let heard = false;
        rec.onresult = (e) => {
            let interim = "";
            for (let i = e.resultIndex; i < e.results.length; i++) {
                const t = e.results[i][0].transcript;
                if (e.results[i].isFinal)
                    finalText += t;
                else
                    interim += t;
            }
            const said = (finalText + interim).trim();
            if (said)
                heard = true;
            inp.value = (base ? base + " " : "") + said;
        };
        rec.onerror = (e) => {
            if (e && (e.error === "not-allowed" || e.error === "service-not-allowed")) {
                mic.hidden = true;
            }
            heard = false;
            stop();
        };
        rec.onend = () => {
            mic.classList.remove("qlmic-live");
            _captureVoiceRec = null;
            if (heard && inp.value.trim())
                deps.quickLog();
        };
        _captureVoiceRec = rec;
        mic.classList.add("qlmic-live");
        try {
            rec.start();
        }
        catch {
            stop();
        }
    });
}
